BEGIN;
ALTER TABLE pooling.pool ADD COLUMN IF NOT EXISTS strategy_code text,ADD COLUMN IF NOT EXISTS valid_from date,ADD COLUMN IF NOT EXISTS valid_until date,ADD COLUMN IF NOT EXISTS eligible_asset_codes text[] NOT NULL DEFAULT '{}',ADD COLUMN IF NOT EXISTS mudarib_profit_share numeric(9,6),ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT clock_timestamp();
ALTER TABLE pooling.pool DROP CONSTRAINT IF EXISTS pool_status_check;ALTER TABLE pooling.pool ADD CONSTRAINT pool_status_check CHECK(status IN('DRAFT','ACTIVE','SUSPENDED','CLOSED'));ALTER TABLE pooling.pool ADD CONSTRAINT pool_period_valid CHECK(valid_until IS NULL OR valid_until>=valid_from);ALTER TABLE pooling.pool ADD CONSTRAINT pool_mudarib_share_valid CHECK(mudarib_profit_share IS NULL OR mudarib_profit_share BETWEEN 0 AND 100);
CREATE TABLE IF NOT EXISTS pooling.funding_source(pool_id text NOT NULL REFERENCES pooling.pool(pool_id),source_id text NOT NULL,source_type text NOT NULL CHECK(source_type IN('BANK_EQUITY','IAH_RESTRICTED','IAH_UNRESTRICTED')),amount numeric(30,12) NOT NULL CHECK(amount>0),currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),mandate_asset_codes text[] NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(pool_id,source_id),CHECK((source_type='IAH_RESTRICTED' AND cardinality(mandate_asset_codes)>0)OR(source_type<>'IAH_RESTRICTED' AND cardinality(mandate_asset_codes)=0)),FOREIGN KEY(pool_id,currency_code)REFERENCES pooling.pool(pool_id,currency_code));
COMMIT;
